        return a + b > c and a + c > b and b + c > a

    def is_right_angle_triangle(a, b, c):
        sides = [a, b, c]
        max_side = max(sides)
        sides.remove(max_side)
        return max_side ** 2 == sides[0] ** 2 + sides[1] ** 2

    if is_triangle(a, b, c) and is_right_angle_triangle(a, b, c):
        return True
    else:
        return False

