def right_angle_triangle(a, b, c):
    # Validate the input to ensure all sides are positive integers
    if a <= 0 or b <= 0 or c <= 0:
        return False

    # Check if the sum of any two sides is greater than the third side to determine if a triangle can be formed
    if a + b <= c or a + c <= b or b + c <= a:
        return False

    # Calculate the squares of the sides
    a_squared = a ** 2
    b_squared = b ** 2
    c_squared = c ** 2

    # Identify the longest side
    longest_side = max(a_squared, b_squared, c_squared)

    # Check if the sum of the squares of the two shorter sides is equal to the square of the longest side
    if longest_side == a_squared + b_squared:
        return True
    elif longest_side == a_squared + c_squared:
        return True
    elif longest_side == b_squared + c_squared:
        return True
    else:
        return False
