    }

    if planet1 not in planets or planet2 not in planets:
        return ()

    orbit1 = planets[planet1]
    orbit2 = planets[planet2]

    if orbit1 > orbit2:
        orbit1, orbit2 = orbit2, orbit1

    result = [planet for planet, orbit in planets.items() if orbit1 < orbit < orbit2]
    result.sort(key=lambda x: planets[x])

