def separate_paren_groups(paren_string: str) -> List[str]:
    # Remove spaces from the input string
    paren_string = paren_string.replace(" ", "")

    # Identify and extract individual groups of nested parentheses
    groups = []
    current_group = ""
    open_braces = 0
    for char in paren_string:
        if char == "(":
            open_braces += 1
        elif char == ")":
            open_braces -= 1

        current_group += char

        if open_braces == 0:
            groups.append(current_group)
            current_group = ""

    # Check if each group is balanced
    def is_balanced(group):
        stack = []
        for char in group:
            if char == "(":
                stack.append(char)
            elif char == ")":
                if not stack:
                    return False
                stack.pop()
        return len(stack) == 0

    # Separate the balanced groups into separate strings
    balanced_groups = [group for group in groups if is_balanced(group)]

